selector .elementor-button:before{
        content: '';
    border: inherit;
    position: absolute;
    left: 4px;
    top: 4px;
    right: 4px;
    bottom: 4px;
    opacity: .4;
}

/* ===== FORCE SIDE IMAGE ON MOBILE ===== */
@media (max-width:767px){

/* cancel elementor stacking */
selector.elementor-position-top .elementor-image-box-wrapper{
    display:flex !important;
    flex-direction:row !important;
    align-items:center !important;
    text-align:left !important;
    gap:12px;
}

/* fix image size */
selector .elementor-image-box-img{
    flex:0 0 70px;
    max-width:70px;
}

/* allow text to take space */
selector .elementor-image-box-content{
    flex:1;
}

/* stop title center alignment */
selector .elementor-image-box-title,
selector .elementor-image-box-description{
    text-align:left !important;
}

}

